1	import 'dart:async';
2	
3	import 'package:cerne/core/network/connectivity_checker.dart';
4	import 'package:cerne/core/network/failure.dart';
5	import 'package:cerne/features/chat/domain/entities/bookmark_status.dart';
6	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
7	import 'package:cerne/features/chat/domain/entities/chat_stream_event.dart';
8	import 'package:cerne/features/chat/domain/entities/chat_title_deriver.dart';
9	import 'package:cerne/features/chat/domain/entities/insight_trigger.dart';
10	import 'package:cerne/features/chat/domain/entities/proactive_insight.dart';
11	import 'package:cerne/features/chat/domain/repositories/chat_repository.dart';
12	import 'package:cerne/features/chat/presentation/bloc/chat_event.dart';
13	import 'package:cerne/features/chat/presentation/bloc/chat_state.dart';
14	import 'package:cerne/features/entries/domain/entities/entry.dart';
15	import 'package:cerne/features/entries/domain/usecases/create_entry_usecase.dart';
16	import 'package:flutter_bloc/flutter_bloc.dart';
17	import 'package:fpdart/fpdart.dart';
18	
19	/// The Home/Chat screen's own live conversation — streaming, retry, lazy
20	/// session creation, composer gating (contracts/chat-bloc.md). Depends only
21	/// on `ChatRepository` + `ConnectivityChecker` — never `ChatSessionsBloc`
22	/// nor `SessionBloc` (research.md R7).
23	class ChatBloc extends Bloc<ChatEvent, ChatState> {
24	  ChatBloc({
25	    required ChatRepository chatRepository,
26	    required ConnectivityChecker connectivityChecker,
27	    required CreateEntryUseCase createEntryUseCase,
28	    Duration insightInactivityTimeout = const Duration(minutes: 2),
29	  }) : _chatRepository = chatRepository, // ignore: prefer_initializing_formals
30	       _connectivityChecker = connectivityChecker, // ignore: prefer_initializing_formals
31	       _createEntryUseCase = createEntryUseCase, // ignore: prefer_initializing_formals
32	       _insightInactivityTimeout = insightInactivityTimeout, // ignore: prefer_initializing_formals
33	       super(const ChatLoading()) {
34	    on<ChatStarted>(_onStarted);
35	    on<ConversationSelected>(_onConversationSelected);
36	    on<NewConversationRequested>(_onNewConversationRequested);
37	    on<MessageSubmitted>(_onMessageSubmitted);
38	    on<MessageRetryRequested>(_onMessageRetryRequested);
39	    on<BookmarkTapped>(_onBookmarkTapped);
40	    on<ChatConnectivityChanged>(_onConnectivityChanged);
41	    on<ChatForegroundChanged>(_onForegroundChanged);
42	    on<InsightInactivityTimerFired>(_onInsightInactivityTimerFired);
43	    on<InsightDismissed>(_onInsightDismissed);
44	    _connectivitySubscription = connectivityChecker.onConnectivityChanged.listen(
45	      (isOnline) => add(ChatConnectivityChanged(isOnline)),
46	    );
47	  }
48	
49	  final ChatRepository _chatRepository;
50	  final ConnectivityChecker _connectivityChecker;
51	  final CreateEntryUseCase _createEntryUseCase;
52	  final Duration _insightInactivityTimeout;
53	  late final StreamSubscription<bool> _connectivitySubscription;
54	  final _reauthController = StreamController<void>.broadcast();
55	
56	  /// Guards against a resolved/superseded turn's late emit (defensive,
57	  /// research.md R9) — bumped on every new turn and on every conversation
58	  /// switch/new-conversation request.
59	  int _turnGeneration = 0;
60	
61	  // Insight mechanism bookkeeping — private, never part of ChatState
62	  // (research.md R1). None of these six fields are read/written outside this
63	  // bloc's own handlers.
64	  int _insightMessageCount = 0;
65	  bool _insightInFlight = false;
66	  InsightTrigger? _pendingInsightTrigger;
67	  int _insightGeneration = 0;
68	  bool _isForegrounded = true;
69	  Timer? _inactivityTimer;
70	
71	  /// FR-004's single suspension condition — folds "deferred", "in flight",
72	  /// and "a card is awaiting dismissal" into one boolean (research.md R5).
73	  bool get _insightSuspended {
74	    final current = state;
75	    return _insightInFlight ||
76	        _pendingInsightTrigger != null ||
77	        (current is ChatReady && current.insight != null);
78	  }
79	
80	  /// A one-shot side effect, not a state (research.md R3/R7) —
81	  /// `HomeChatShellPage` listens to this to raise the "Sessão expirada"
82	  /// overlay.
83	  Stream<void> get reauthRequired => _reauthController.stream;
84	
85	  Future<void> _onStarted(ChatStarted event, Emitter<ChatState> emit) async {
86	    _resetInsightMechanism();
87	    final isOnline = await _connectivityChecker.hasConnection();
88	    final lastId = await _chatRepository.lastActiveSessionId;
89	    if (lastId == null) {
90	      emit(
91	        ChatReady(
92	          sessionId: null,
93	          messages: const [],
94	          isOffline: !isOnline,
95	          awaitingResponse: false,
96	        ),
97	      );
98	      _armInactivityTimer();
99	      return;
100	    }
101	    await _loadSession(lastId, emit, isOffline: !isOnline);
102	    _armInactivityTimer();
103	  }
104	
105	  Future<void> _onConversationSelected(
106	    ConversationSelected event,
107	    Emitter<ChatState> emit,
108	  ) async {
109	    _turnGeneration++;
110	    _resetInsightMechanism();
111	    final isOnline = await _connectivityChecker.hasConnection();
112	    await _loadSession(event.sessionId, emit, isOffline: !isOnline);
113	    _armInactivityTimer();
114	  }
115	
116	  Future<void> _onNewConversationRequested(
117	    NewConversationRequested event,
118	    Emitter<ChatState> emit,
119	  ) async {
120	    _turnGeneration++;
121	    _resetInsightMechanism();
122	    final current = state;
123	    final isOffline = current is ChatReady ? current.isOffline : false;
124	    await _chatRepository.setLastActiveSessionId(null);
125	    emit(
126	      ChatReady(
127	        sessionId: null,
128	        messages: const [],
129	        isOffline: isOffline,
130	        awaitingResponse: false,
131	      ),
132	    );
133	    _armInactivityTimer();
134	  }
135	
136	  /// One independent request/response per message — never involves
137	  /// `_turnGeneration`, never touches `awaitingResponse`/`messages`, so a
138	  /// save can never block the rest of the screen (FR-006).
139	  Future<void> _onBookmarkTapped(
140	    BookmarkTapped event,
141	    Emitter<ChatState> emit,
142	  ) async {
143	    final current = state;
144	    if (current is! ChatReady) return;
145	
146	    final index = current.messages.indexWhere((m) => m.id == event.messageId);
147	    if (index == -1) return;
148	    final message = current.messages[index];
149	
150	    if (message.role != ChatRole.user) return; // FR-001, defensive
151	    if (message.isOptimistic) return; // research.md R6
152	
153	    final currentStatus = current.bookmarkStatusFor(message.id);
154	    if (currentStatus == BookmarkStatus.saving || currentStatus == BookmarkStatus.saved) {
155	      return; // FR-003/FR-007
156	    }
157	
158	    emit(
159	      current.copyWith(
160	        bookmarks: {...current.bookmarks, message.id: BookmarkStatus.saving},
161	      ),
162	    );
163	
164	    final created = await _createEntryUseCase(
165	      message.content,
166	      EntrySource.chat,
167	      chatMessageId: message.id,
168	      occurredAt: message.createdAt,
169	    );
170	
171	    final latest = state;
172	    if (latest is! ChatReady) return; // navigated away mid-save
173	
174	    await created.match(
175	      (failure) async {
176	        if (failure is AuthExpiredFailure) _reauthController.add(null); // research.md R9
177	        emit(
178	          latest.copyWith(
179	            bookmarks: {...latest.bookmarks, message.id: BookmarkStatus.error},
180	          ),
181	        );
182	      },
183	      (entry) async {
184	        await _chatRepository.recordMessageSaved(
185	          chatMessageId: message.id,
186	          entryId: entry.id,
187	        );
188	        final afterRecord = state;
189	        if (afterRecord is! ChatReady) return;
190	        emit(
191	          afterRecord.copyWith(
192	            bookmarks: {...afterRecord.bookmarks, message.id: BookmarkStatus.saved},
193	          ),
194	        );
195	      },
196	    );
197	  }
198	
199	  void _onConnectivityChanged(
200	    ChatConnectivityChanged event,
201	    Emitter<ChatState> emit,
202	  ) {
203	    final current = state;
204	    if (current is! ChatReady) return;
205	    emit(current.copyWith(isOffline: !event.isOnline));
206	  }
207	
208	  /// The shared fetch-with-cache-fallback path (Clarification 3).
209	  Future<void> _loadSession(
210	    String sessionId,
211	    Emitter<ChatState> emit, {
212	    required bool isOffline,
213	  }) async {
214	    final result = await _chatRepository.listMessages(sessionId);
215	    await result.match(
216	      (failure) async {
217	        if (failure is AuthExpiredFailure) _reauthController.add(null);
218	        final cached = _chatRepository.cachedMessages(sessionId);
219	        if (cached == null) {
220	          // Never opened while online — the "standard no-connection state"
221	          // instead of any content (Edge Cases).
222	          emit(
223	            ChatReady(
224	              sessionId: sessionId,
225	              messages: const [],
226	              isOffline: isOffline,
227	              awaitingResponse: false,
228	              loadFailure: failure,
229	            ),
230	          );
231	        } else {
232	          emit(
233	            ChatReady(
234	              sessionId: sessionId,
235	              messages: cached,
236	              isOffline: isOffline,
237	              awaitingResponse: false,
238	              bookmarks: _seedBookmarks(cached),
239	            ),
240	          );
241	        }
242	      },
243	      (messages) async {
244	        await _chatRepository.setLastActiveSessionId(sessionId);
245	        emit(
246	          ChatReady(
247	            sessionId: sessionId,
248	            messages: messages,
249	            isOffline: isOffline,
250	            awaitingResponse: false,
251	            bookmarks: _seedBookmarks(messages),
252	          ),
253	        );
254	      },
255	    );
256	  }
257	
258	  /// FR-008 — rebuilt from scratch on every `_loadSession` call (never
259	  /// incrementally patched): for every user message already recorded as
260	  /// saved (research.md R1), seed that id as `saved`; every other message is
261	  /// left absent, i.e. `idle`.
262	  Map<String, BookmarkStatus> _seedBookmarks(List<ChatMessage> messages) {
263	    final result = <String, BookmarkStatus>{};
264	    for (final m in messages) {
265	      if (m.role != ChatRole.user) continue;
266	      if (_chatRepository.savedEntryIdFor(m.id) != null) {
267	        result[m.id] = BookmarkStatus.saved;
268	      }
269	    }
270	    return result;
271	  }
272	
273	  Future<void> _onMessageSubmitted(
274	    MessageSubmitted event,
275	    Emitter<ChatState> emit,
276	  ) async {
277	    final current = state;
278	    if (current is! ChatReady || !current.canSend) return;
279	
280	    if (!await _connectivityChecker.hasConnection()) {
281	      // FR-012 — blocked client-side, never attempted. The composer's own
282	      // isOffline flag (R8's live stream) reflects this on its own shortly.
283	      return;
284	    }
285	
286	    final generation = ++_turnGeneration;
287	    final now = DateTime.now();
288	    final optimisticUser = ChatMessage(
289	      id: 'local-${now.microsecondsSinceEpoch}',
290	      sessionId: current.sessionId ?? '',
291	      role: ChatRole.user,
292	      content: event.text,
293	      seq: current.messages.length,
294	      status: ChatMessageStatus.complete,
295	      retryCount: 0,
296	      createdAt: now,
297	    );
298	    final optimisticAssistant = ChatMessage(
299	      id: 'local-${now.microsecondsSinceEpoch}-response',
300	      sessionId: current.sessionId ?? '',
301	      role: ChatRole.assistant,
302	      content: '',
303	      seq: current.messages.length + 1,
304	      status: ChatMessageStatus.streaming,
305	      retryCount: 0,
306	      createdAt: now,
307	    );
308	
309	    if (!_insightSuspended) {
310	      _insightMessageCount++;
311	      if (_insightMessageCount % 5 == 0) {
312	        _pendingInsightTrigger ??= InsightTrigger(
313	          type: InsightTriggerType.messageCount,
314	          triggerKey: InsightTriggerKeyBuilder.forMessageCount(_insightMessageCount),
315	        );
316	      }
317	    }
318	    _armInactivityTimer(); // FR-001b — resets "time since last message sent" now
319	
320	    emit(
321	      current.copyWith(
322	        messages: [...current.messages, optimisticUser, optimisticAssistant],
323	        awaitingResponse: true,
324	      ),
325	    );
326	
327	    String sessionId;
328	    if (current.sessionId == null) {
329	      final created = await _chatRepository.createSession(
330	        title: ChatTitleDeriver.derive(event.text),
331	      );
332	      if (generation != _turnGeneration) return;
333	      final maybeId = created.match((_) => null, (s) => s.id);
334	      if (maybeId == null) {
335	        final failure = created.getLeft().toNullable()!;
336	        await _failTurn(emit, current.sessionId ?? '', optimisticAssistant.id, failure);
337	        return;
338	      }
339	      sessionId = maybeId;
340	      await _chatRepository.setLastActiveSessionId(sessionId);
341	    } else {
342	      sessionId = current.sessionId!;
343	    }
344	
345	    final stream = _chatRepository.sendMessage(
346	      sessionId: sessionId,
347	      content: event.text,
348	    );
349	    await _consumeTurn(
350	      stream,
351	      emit,
352	      generation: generation,
353	      sessionId: sessionId,
354	      optimisticUserId: optimisticUser.id,
355	      optimisticAssistantId: optimisticAssistant.id,
356	    );
357	  }
358	
359	  Future<void> _onMessageRetryRequested(
360	    MessageRetryRequested event,
361	    Emitter<ChatState> emit,
362	  ) async {
363	    final current = state;
364	    if (current is! ChatReady || current.awaitingResponse) {
365	      return;
366	    }
367	    final index = current.messages.indexWhere(
368	      (m) =>
369	          m.role == ChatRole.assistant &&
370	          m.status == ChatMessageStatus.failed &&
371	          _userMessageIdFor(current.messages, m) == event.userMessageId,
372	    );
373	    if (index == -1) return;
374	    if (!await _connectivityChecker.hasConnection()) return; // FR-012
375	
376	    final userMessage = current.messages[index - 1];
377	    if (userMessage.isOptimistic) {
378	      // The turn's very first `createSession` call failed (FR-006) — there
379	      // is no persisted session/message yet for `retryMessage` to target, so
380	      // re-run the same lazy-creation path `_onMessageSubmitted` takes.
381	      await _retryLazySessionCreation(current, index, userMessage, emit);
382	      return;
383	    }
384	    if (current.sessionId == null) return;
385	
386	    final generation = ++_turnGeneration;
387	    final now = DateTime.now();
388	    final placeholder = ChatMessage(
389	      id: 'local-${now.microsecondsSinceEpoch}-retry',
390	      sessionId: current.sessionId!,
391	      role: ChatRole.assistant,
392	      content: '',
393	      seq: current.messages[index].seq,
394	      status: ChatMessageStatus.streaming,
395	      retryCount: current.messages[index].retryCount + 1,
396	      createdAt: now,
397	    );
398	    final updatedMessages = [...current.messages];
399	    updatedMessages[index] = placeholder;
400	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
401	
402	    final stream = _chatRepository.retryMessage(
403	      sessionId: current.sessionId!,
404	      userMessageId: event.userMessageId,
405	    );
406	    await _consumeTurn(
407	      stream,
408	      emit,
409	      generation: generation,
410	      sessionId: current.sessionId!,
411	      optimisticUserId: null,
412	      optimisticAssistantId: placeholder.id,
413	    );
414	  }
415	
416	  /// Retries a turn whose lazy `createSession` call (FR-010) itself failed
417	  /// before any session ever existed — reuses `createSession` +
418	  /// `sendMessage` with the original user message's own content, exactly as
419	  /// `_onMessageSubmitted` does for a brand-new conversation.
420	  Future<void> _retryLazySessionCreation(
421	    ChatReady current,
422	    int index,
423	    ChatMessage userMessage,
424	    Emitter<ChatState> emit,
425	  ) async {
426	    final generation = ++_turnGeneration;
427	    final now = DateTime.now();
428	    final placeholder = ChatMessage(
429	      id: 'local-${now.microsecondsSinceEpoch}-retry',
430	      sessionId: userMessage.sessionId,
431	      role: ChatRole.assistant,
432	      content: '',
433	      seq: current.messages[index].seq,
434	      status: ChatMessageStatus.streaming,
435	      retryCount: current.messages[index].retryCount + 1,
436	      createdAt: now,
437	    );
438	    final updatedMessages = [...current.messages];
439	    updatedMessages[index] = placeholder;
440	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
441	
442	    final created = await _chatRepository.createSession(
443	      title: ChatTitleDeriver.derive(userMessage.content),
444	    );
445	    if (generation != _turnGeneration) return;
446	    final maybeId = created.match((_) => null, (s) => s.id);
447	    if (maybeId == null) {
448	      final failure = created.getLeft().toNullable()!;
449	      await _failTurn(emit, userMessage.sessionId, placeholder.id, failure);
450	      return;
451	    }
452	    await _chatRepository.setLastActiveSessionId(maybeId);
453	
454	    final latest = state;
455	    if (latest is! ChatReady || generation != _turnGeneration) return;
456	    emit(latest.copyWith(sessionId: maybeId));
457	
458	    final stream = _chatRepository.sendMessage(
459	      sessionId: maybeId,
460	      content: userMessage.content,
461	    );
462	    await _consumeTurn(
463	      stream,
464	      emit,
465	      generation: generation,
466	      sessionId: maybeId,
467	      optimisticUserId: userMessage.id,
468	      optimisticAssistantId: placeholder.id,
469	    );
470	  }
471	
472	  /// Shared `emit.forEach`-driven stream consumption for both a fresh send
473	  /// and a retry.
474	  Future<void> _consumeTurn(
475	    Stream<Either<Failure, ChatStreamEvent>> stream,
476	    Emitter<ChatState> emit, {
477	    required int generation,
478	    required String sessionId,
479	    required String? optimisticUserId,
480	    required String optimisticAssistantId,
481	  }) async {
482	    var assistantId = optimisticAssistantId;
483	    await emit.forEach<Either<Failure, ChatStreamEvent>>(
484	      stream,
485	      onData: (result) {
486	        final latest = state;
487	        if (generation != _turnGeneration || latest is! ChatReady) {
488	          return latest;
489	        }
490	        return result.match((failure) {
491	          if (failure is AuthExpiredFailure) _reauthController.add(null);
492	          return _applyFailure(latest, assistantId, failure);
493	        }, (event) => switch (event) {
494	          MessageCreated() => () {
495	            assistantId = event.assistantMessageId;
496	            return _reconcileIds(
497	              latest,
498	              optimisticUserId,
499	              event.userMessageId,
500	              optimisticAssistantId,
501	              event.assistantMessageId,
502	            );
503	          }(),
504	          ContextReceived() => latest,
505	          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
506	          StreamDone(assistantMessageId: final id) =>
507	            _completeMessage(latest, id).copyWith(awaitingResponse: false),
508	        });
509	      },
510	    );
511	    await _reconcileSilentFailure(emit, sessionId, assistantId, generation);
512	    if (generation == _turnGeneration) await _onTurnResolved(sessionId, emit);
513	  }
514	
515	  /// A failure yielded as (or before) the stream's very first item leaves the
516	  /// bubble `failed` with empty content even though the backend may have
517	  /// kept generating in the background and already persisted the full
518	  /// answer by the time the stream closed (e.g. a transient network drop
519	  /// right after `message_created`, before any token arrives). One
520	  /// best-effort refetch here closes that gap without needing the user to
521	  /// leave and come back. Only acts on an empty-content failure — a failure
522	  /// after partial tokens (FR-005) is left exactly as the stream reported
523	  /// it. Note this is a best-effort recovery for a genuinely slow backend,
524	  /// not a substitute for parsing the stream correctly in the first place —
525	  /// it loses the race whenever the backend is still generating (slow/live
526	  /// answers can take several seconds longer than this one refetch waits
527	  /// for).
528	  Future<void> _reconcileSilentFailure(
529	    Emitter<ChatState> emit,
530	    String sessionId,
531	    String assistantId,
532	    int generation,
533	  ) async {
534	    final seeded = state;
535	    if (seeded is! ChatReady || generation != _turnGeneration) return;
536	    final index = seeded.messages.indexWhere((m) => m.id == assistantId);
537	    if (index == -1) return;
538	    final message = seeded.messages[index];
539	    if (message.status != ChatMessageStatus.failed || message.content.isNotEmpty) {
540	      return;
541	    }
542	
543	    final result = await _chatRepository.listMessages(sessionId);
544	    if (generation != _turnGeneration) return;
545	    result.match((_) {}, (serverMessages) {
546	      ChatMessage? persisted;
547	      for (final m in serverMessages) {
548	        if (m.role == ChatRole.assistant && m.seq == message.seq) {
549	          persisted = m;
550	          break;
551	        }
552	      }
553	      final resolved = persisted;
554	      if (resolved == null ||
555	          resolved.status != ChatMessageStatus.complete ||
556	          resolved.content.isEmpty) {
557	        return;
558	      }
559	      final latest = state;
560	      if (latest is! ChatReady || generation != _turnGeneration) return;
561	      final updated = [
562	        for (final m in latest.messages) if (m.id == assistantId) resolved else m,
563	      ];
564	      emit(latest.copyWith(messages: updated));
565	    });
566	  }
567	
568	  Future<void> _failTurn(
569	    Emitter<ChatState> emit,
570	    String sessionId,
571	    String assistantId,
572	    Failure failure,
573	  ) async {
574	    final latest = state;
575	    if (latest is! ChatReady) return;
576	    emit(_applyFailure(latest, assistantId, failure));
577	    await _onTurnResolved(sessionId, emit);
578	  }
579	
580	  /// `null` for a retry's `userMessageId` — a retry never targets an
581	  /// optimistic question, only an already-persisted one.
582	  ChatReady _reconcileIds(
583	    ChatReady current,
584	    String? optimisticUserId,
585	    String realUserId,
586	    String optimisticAssistantId,
587	    String realAssistantId,
588	  ) {
589	    final updated = [
590	      for (final m in current.messages)
591	        if (optimisticUserId != null && m.id == optimisticUserId)
592	          _withId(m, realUserId)
593	        else if (m.id == optimisticAssistantId)
594	          _withId(m, realAssistantId)
595	        else
596	          m,
597	    ];
598	    return current.copyWith(messages: updated);
599	  }
600	
601	  ChatMessage _withId(ChatMessage message, String id) => ChatMessage(
602	    id: id,
603	    sessionId: message.sessionId,
604	    role: message.role,
605	    content: message.content,
606	    seq: message.seq,
607	    status: message.status,
608	    retryCount: message.retryCount,
609	    createdAt: message.createdAt,
610	  );
611	
612	  ChatReady _appendToken(ChatReady current, String assistantId, String delta) {
613	    final updated = [
614	      for (final m in current.messages)
615	        if (m.id == assistantId) _withContent(m, m.content + delta) else m,
616	    ];
617	    return current.copyWith(messages: updated);
618	  }
619	
620	  // The backend's `done` SSE event carries no authoritative `content`
621	  // (contracts/zod/chat.ts's `sseDoneEventSchema` has only
622	  // `assistantMessageId`/`finishReason`) — the message's own content, built
623	  // up from this turn's `TokenReceived` deltas, is already the full answer.
624	  ChatReady _completeMessage(ChatReady current, String assistantId) {
625	    final updated = [
626	      for (final m in current.messages)
627	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.complete) else m,
628	    ];
629	    return current.copyWith(messages: updated);
630	  }
631	
632	  /// Keeps whatever partial `content` had already accumulated — never
633	  /// removed, hidden, or blanked (FR-005).
634	  ChatReady _applyFailure(
635	    ChatReady current,
636	    String assistantId,
637	    Failure failure,
638	  ) {
639	    final updated = [
640	      for (final m in current.messages)
641	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.failed) else m,
642	    ];
643	    return current.copyWith(messages: updated, awaitingResponse: false);
644	  }
645	
646	  ChatMessage _withContent(ChatMessage message, String content) => ChatMessage(
647	    id: message.id,
648	    sessionId: message.sessionId,
649	    role: message.role,
650	    content: content,
651	    seq: message.seq,
652	    status: message.status,
653	    retryCount: message.retryCount,
654	    createdAt: message.createdAt,
655	  );
656	
657	  ChatMessage _withStatus(ChatMessage message, ChatMessageStatus status) =>
658	      ChatMessage(
659	        id: message.id,
660	        sessionId: message.sessionId,
661	        role: message.role,
662	        content: message.content,
663	        seq: message.seq,
664	        status: status,
665	        retryCount: message.retryCount,
666	        createdAt: message.createdAt,
667	      );
668	
669	  /// Position-matching (research.md R10) — the id of the user message
670	  /// immediately preceding [message] in [messages], or `null` if it isn't
671	  /// immediately preceded by one.
672	  String? _userMessageIdFor(List<ChatMessage> messages, ChatMessage message) {
673	    final index = messages.indexWhere((m) => m.id == message.id);
674	    if (index <= 0) return null;
675	    final preceding = messages[index - 1];
676	    return preceding.role == ChatRole.user ? preceding.id : null;
677	  }
678	
679	  // Conversation (re)opened — FR-009's "counters start fresh" moment.
680	  // Called from _onStarted / _onConversationSelected /
681	  // _onNewConversationRequested, right before emitting the fresh ChatReady.
682	  void _resetInsightMechanism() {
683	    _insightGeneration++;
684	    _insightMessageCount = 0;
685	    _insightInFlight = false;
686	    _pendingInsightTrigger = null;
687	    _inactivityTimer?.cancel();
688	  }
689	
690	  void _armInactivityTimer() {
691	    _inactivityTimer?.cancel();
692	    if (!_isForegrounded || _insightSuspended) return;
693	    _inactivityTimer = Timer(
694	      _insightInactivityTimeout,
695	      () => add(InsightInactivityTimerFired(DateTime.now())),
696	    );
697	  }
698	
699	  void _onForegroundChanged(
700	    ChatForegroundChanged event,
701	    Emitter<ChatState> emit,
702	  ) {
703	    _isForegrounded = event.isForegrounded;
704	    if (!_isForegrounded) {
705	      _inactivityTimer?.cancel();
706	      return;
707	    }
708	    _armInactivityTimer(); // FR-010 — always a fresh 2 minutes, never a resumed partial count
709	  }
710	
711	  Future<void> _onInsightInactivityTimerFired(
712	    InsightInactivityTimerFired event,
713	    Emitter<ChatState> emit,
714	  ) async {
715	    final current = state;
716	    if (current is! ChatReady || current.sessionId == null) return; // research.md R6
717	    if (_insightSuspended) return; // defensive — the timer is cancelled the instant suspension begins
718	    final trigger = InsightTrigger(
719	      type: InsightTriggerType.inactivity,
720	      triggerKey: InsightTriggerKeyBuilder.forInactivity(event.firedAt),
721	    );
722	    if (current.awaitingResponse) {
723	      _pendingInsightTrigger ??= trigger; // FR-003 — defer until the turn resolves
724	      return;
725	    }
726	    await _startInsightAttempt(trigger, sessionId: current.sessionId!, emit: emit);
727	  }
728	
729	  void _onInsightDismissed(InsightDismissed event, Emitter<ChatState> emit) {
730	    final current = state;
731	    if (current is! ChatReady || current.insight == null) return;
732	    emit(current.copyWith(clearInsight: true));
733	    _armInactivityTimer(); // FR-004/FR-008 — suspension ends, fresh window starts
734	  }
735	
736	  Future<void> _startInsightAttempt(
737	    InsightTrigger trigger, {
738	    required String sessionId,
739	    required Emitter<ChatState> emit,
740	  }) async {
741	    _inactivityTimer?.cancel();
742	    _pendingInsightTrigger = null;
743	    _insightInFlight = true;
744	    final generation = _insightGeneration;
745	    final anchorIndex = (state as ChatReady).messages.length;
746	
747	    if (!await _connectivityChecker.hasConnection()) {
748	      _insightInFlight = false; // FR-007 — never attempted; resolved like a failure
749	      if (generation == _insightGeneration) _armInactivityTimer();
750	      return;
751	    }
752	
753	    final result = await _chatRepository.createInsight(
754	      sessionId: sessionId,
755	      triggerType: trigger.type,
756	      triggerKey: trigger.triggerKey,
757	    );
758	
759	    _insightInFlight = false;
760	    if (generation != _insightGeneration) return; // stale — conversation switched away mid-flight
761	
762	    final latest = state;
763	    if (latest is! ChatReady) return;
764	
765	    result.match(
766	      (failure) {
767	        if (failure is AuthExpiredFailure) _reauthController.add(null);
768	        _armInactivityTimer(); // FR-006 — no card, no indicator; occurrence fully resolved
769	      },
770	      (content) => emit(
771	        latest.copyWith(insight: ProactiveInsight(content: content, anchorIndex: anchorIndex)),
772	      ),
773	    );
774	  }
775	
776	  // Called once per turn resolution — the end of _consumeTurn (after
777	  // _reconcileSilentFailure) and inside _failTurn, both now `Future<void>`.
778	  Future<void> _onTurnResolved(String sessionId, Emitter<ChatState> emit) async {
779	    final hadPending = _pendingInsightTrigger != null;
780	    final trigger = _pendingInsightTrigger;
781	    if (trigger != null) {
782	      final current = state;
783	      if (current is ChatReady && !current.awaitingResponse) {
784	        await _startInsightAttempt(trigger, sessionId: sessionId, emit: emit);
785	      }
786	    }
787	    // Only re-arm here if a deferred trigger just finished resolving without
788	    // a card (failed/skipped) — a turn with no pending trigger leaves
789	    // whatever timer _onMessageSubmitted already armed at send-time alone
790	    // (research.md R4).
791	    if (hadPending && !_insightSuspended) _armInactivityTimer();
792	  }
793	
794	  @override
795	  Future<void> close() {
796	    unawaited(_connectivitySubscription.cancel());
797	    unawaited(_reauthController.close());
798	    _inactivityTimer?.cancel();
799	    return super.close();
800	  }
801	}
