1	import 'package:cerne/core/network/failure.dart';
2	import 'package:cerne/features/chat/domain/entities/bookmark_status.dart';
3	import 'package:cerne/features/chat/domain/entities/chat_message.dart';
4	import 'package:cerne/features/chat/domain/entities/proactive_insight.dart';
5	import 'package:equatable/equatable.dart';
6	
7	sealed class ChatState extends Equatable {
8	  const ChatState();
9	
10	  @override
11	  List<Object?> get props => [];
12	}
13	
14	/// Only while resuming `lastActiveSessionId` on `ChatStarted`.
15	class ChatLoading extends ChatState {
16	  const ChatLoading();
17	}
18	
19	/// Everything else — an existing conversation, the empty "Novo Chat" state,
20	/// or an outright load failure with nothing cached to fall back to — are all
21	/// one state shape so the screen never has to discard/rebuild its
22	/// `Scaffold`/`AppBar` switching between them.
23	class ChatReady extends ChatState {
24	  const ChatReady({
25	    required this.sessionId,
26	    required this.messages,
27	    required this.isOffline,
28	    required this.awaitingResponse,
29	    this.loadFailure,
30	    this.bookmarks = const {},
31	    this.insight,
32	  });
33	
34	  /// `null` = empty conversation, no session created yet (FR-010).
35	  final String? sessionId;
36	
37	  /// `[]` for an empty conversation.
38	  final List<ChatMessage> messages;
39	  final bool isOffline;
40	
41	  /// research.md R9 — gates the composer, true during a send/retry turn.
42	  final bool awaitingResponse;
43	
44	  /// Set only when selecting an existing session's history failed outright
45	  /// **and** nothing is cached for it (Clarification 3's no-content edge
46	  /// case).
47	  final Failure? loadFailure;
48	
49	  /// Per-message bookmark sub-state, keyed by `ChatMessage.id` — an absent
50	  /// key means `BookmarkStatus.idle` (research.md R5).
51	  final Map<String, BookmarkStatus> bookmarks;
52	
53	  /// `null` = no card visible (FR-004). Never persisted/reconstructed
54	  /// (FR-009) — always `null` on a fresh `ChatReady`.
55	  final ProactiveInsight? insight;
56	
57	  bool get canSend => !isOffline && !awaitingResponse && loadFailure == null;
58	
59	  BookmarkStatus bookmarkStatusFor(String messageId) =>
60	      bookmarks[messageId] ?? BookmarkStatus.idle;
61	
62	  static const _unset = Object();
63	
64	  ChatReady copyWith({
65	    String? sessionId,
66	    bool clearSessionId = false,
67	    List<ChatMessage>? messages,
68	    bool? isOffline,
69	    bool? awaitingResponse,
70	    Object? loadFailure = _unset,
71	    Map<String, BookmarkStatus>? bookmarks,
72	    ProactiveInsight? insight,
73	    bool clearInsight = false,
74	  }) {
75	    return ChatReady(
76	      sessionId: clearSessionId ? null : (sessionId ?? this.sessionId),
