        () => createEntryUseCase(
          any(),
          any(),
          chatMessageId: any(named: 'chatMessageId'),
          occurredAt: any(named: 'occurredAt'),
        ),
      ).thenAnswer((_) => completer.future);
      when(() => chatRepository.createSession(title: any(named: 'title')))
          .thenAnswer((_) async => Right(_buildSession()));
